scripts.build:dafny:
dafny build --target js dafny/Schema.dfy dafny/Syntax.dfy dafny/Eval.dfy dafny/Coherence.dfy dafny/Transition.dfy --output dist/verifier.js --no-verify && rm -f dist/verifier-js.dtr && mv dist/verifier.js dist/verifier.cjs && printf '
// Appended by build:dafny: expose file-local Dafny modules to the TS wrappers.
module.exports = { _dafny, Schema, Syntax, Eval, Coherence, Transition };
' >> dist/verifier.cjs
